<script setup lang="ts">
import { changeType, initial, lines, type Field } from '../../adapters/editing.js';
import ScalarInput from './ScalarInput.vue';
import { manual } from '../../stores/manual.js';
const props = defineProps<{ field: Field; state?: boolean; path: string }>();
const types = [{ id: 'boolean', name: 'Да / Нет' }, { id: 'integer', name: 'Целое число' }, { id: 'number', name: 'Число' }, { id: 'enum', name: 'Выбор из списка' }, { id: 'string', name: 'Текст' }];
function type(event: Event) { changeType(props.field, (event.target as HTMLSelectElement).value); if (props.state) props.field.initial = initial(props.field); }
</script>
<template><div class="form-grid"><label>Название свойства<input v-model="field.name" required :data-path="path + '/name'"></label><label>Тип значения<select :value="field.type" :data-path="path + '/type'" @change="type"><option v-for="t in types" :key="t.id" :value="t.id">{{ t.name }}</option></select></label><label v-if="manual.advanced.value">Ключ<input v-model="field.id" required :data-path="path + '/id'"></label><label>Описание<input v-model="field.description"></label><template v-if="field.type === 'number' || field.type === 'integer'"><label>Минимум<input v-model.number="field.minimum" type="number" step="any" required :data-path="path + '/minimum'"></label><label>Максимум<input v-model.number="field.maximum" type="number" step="any" required :data-path="path + '/maximum'"></label><label>Единица измерения<input v-model="field.unit" ><small class="field-example">Примеры: %, °C, об/мин. Необязательно.</small></label></template><template v-if="field.type === 'string'"><label>Минимальная длина<input v-model.number="field.min_length" type="number" min="0" required></label><label>Максимальная длина<input v-model.number="field.max_length" type="number" min="0" required></label></template><label v-if="field.type === 'enum'">Варианты, по одному в строке<textarea :value="field.values?.join('\n')" required @input="field.values = lines(($event.target as HTMLTextAreaElement).value)"></textarea></label><label v-if="!state" class="check"><input v-model="field.required" type="checkbox">Значение обязательно</label><ScalarInput v-if="state" :field="field" v-model="field.initial" label="Начальное виртуальное значение" :path="path + '/initial'" /></div><p v-if="state" class="muted">Начальное значение не подтверждает физическое состояние.</p></template>
